mapper.sql:
id = #{task.id} AND tenant_id = #{task.tenantId} AND created_by = #{task.createdBy}
AND owner_instance_id = #{task.ownerInstanceId} AND run_token = #{task.runToken}
AND lease_until > CURRENT_TIMESTAMP(6)

mapper.select:

WHERE t.tenant_id = #{task.tenantId} AND t.id > #{lastId} AND t.id <= #{task.upperBoundId}

AND t.warehouse_id = #{task.warehouseId}
AND t.spare_part_id = #{task.sparePartId}
AND t.work_order_id = #{task.workOrderId}
AND t.transaction_type = #{task.transactionType}
AND t.reference_type = #{task.referenceType}
AND t.created_at >= #{task.startTime}
AND t.created_at <= #{task.endTime}
ORDER BY t.id ASC LIMIT 1000

SELECT COUNT(*) > 0 FROM inventory_export_tasks WHERE id = #{taskId} AND run_token = #{runToken}
AND ((status IN ('QUEUED','RUNNING','CANCEL_REQUESTED') AND lease_until > CURRENT_TIMESTAMP(6))
  OR (status = 'SUCCEEDED' AND expires_at > CURRENT_TIMESTAMP(6)))


SELECT id, tenant_id, error_code, finished_at

FROM inventory_export_tasks

WHERE tenant_id = #{tenantId}

AND status = 'FAILED'

AND finished_at >= #{windowStart}

AND finished_at < #{windowEnd}

AND error_code IN ('TIMEOUT', 'WORKER_LOST', 'IO_FAILED', 'QUERY_FAILED', 'DISK_LIMIT')



    AND (

    finished_at > #{lastFinishedAt}

    OR (finished_at = #{lastFinishedAt} AND id > #{lastTaskId})
    )


ORDER BY finished_at ASC, id ASC

LIMIT 100
